changeSet.sql:
CREATE TABLE app.Roles ( Id UNIQUEIDENTIFIER NOT NULL, Name NVARCHAR(64) NOT NULL, Description NVARCHAR(256) NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_Roles PRIMARY KEY CLUSTERED (Id) ); CREATE UNIQUE INDEX UX_Roles_Name ON app.Roles (Name) WHERE DeletedAt IS NULL;
CREATE TABLE app.Permissions ( Id UNIQUEIDENTIFIER NOT NULL, Code NVARCHAR(64) NOT NULL, Name NVARCHAR(128) NOT NULL, Description NVARCHAR(256) NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_Permissions PRIMARY KEY CLUSTERED (Id) ); CREATE UNIQUE INDEX UX_Permissions_Code ON app.Permissions (Code) WHERE DeletedAt IS NULL;
CREATE TABLE app.RolePermissions ( RoleId UNIQUEIDENTIFIER NOT NULL, PermissionId UNIQUEIDENTIFIER NOT NULL, CONSTRAINT PK_RolePermissions PRIMARY KEY CLUSTERED (RoleId, PermissionId), CONSTRAINT FK_RolePermissions_Roles FOREIGN KEY (RoleId) REFERENCES app.Roles (Id), CONSTRAINT FK_RolePermissions_Permissions FOREIGN KEY (PermissionId) REFERENCES app.Permissions (Id) ); CREATE INDEX IX_RolePermissions_PermissionId ON app.RolePermissions (PermissionId);
CREATE TABLE app.UserRoles ( Id UNIQUEIDENTIFIER NOT NULL, UserId UNIQUEIDENTIFIER NOT NULL, RoleId UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_UserRoles PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_UserRoles_Users FOREIGN KEY (UserId) REFERENCES app.Users (Id), CONSTRAINT FK_UserRoles_Roles FOREIGN KEY (RoleId) REFERENCES app.Roles (Id), CONSTRAINT FK_UserRoles_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id) ); CREATE UNIQUE INDEX UX_UserRoles_UserId_RoleId_TenantId ON app.UserRoles (UserId, RoleId, TenantId) WHERE DeletedAt IS NULL; CREATE INDEX IX_UserRoles_RoleId ON app.UserRoles (RoleId); CREATE INDEX IX_UserRoles_TenantId ON app.UserRoles (TenantId, UserId) WHERE DeletedAt IS NULL;

rollback.sql:
DROP TABLE app.UserRoles;
DROP TABLE app.RolePermissions;
DROP TABLE app.Permissions;
DROP TABLE app.Roles;

changeSet.sql:
DECLARE @Now DATETIME2 = SYSUTCDATETIME();
INSERT INTO app.Roles (Id, Name, Description, CreatedAt, UpdatedAt) VALUES ('11111111-1111-4111-8111-111111111001', N'SuperAdmin', N'Platform operator. Not assigned during registration.', @Now, @Now), ('11111111-1111-4111-8111-111111111002', N'GymOwner', N'Owner of a business workspace.', @Now, @Now), ('11111111-1111-4111-8111-111111111003', N'GymManager', N'Manager of a business workspace.', @Now, @Now), ('11111111-1111-4111-8111-111111111004', N'Trainer', N'Trainer in a business workspace.', @Now, @Now), ('11111111-1111-4111-8111-111111111005', N'Receptionist', N'Receptionist in a business workspace.', @Now, @Now), ('11111111-1111-4111-8111-111111111006', N'Member', N'Member of a business workspace.', @Now, @Now), ('11111111-1111-4111-8111-111111111007', N'PersonalOwner', N'Owner of a personal workspace.', @Now, @Now);
INSERT INTO app.Permissions (Id, Code, Name, Description, CreatedAt, UpdatedAt) VALUES ('22222222-2222-4222-8222-222222222001', N'USER_READ', N'Read users', N'Read user profiles in the current workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222002', N'USER_CREATE', N'Create users', N'Create users in the current workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222003', N'USER_UPDATE', N'Update users', N'Update users in the current workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222004', N'USER_DELETE', N'Delete users', N'Soft-delete users in the current workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222005', N'TENANT_READ', N'Read workspace', N'Read the current workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222006', N'TENANT_UPDATE', N'Update workspace', N'Update the current workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222007', N'TENANT_CREATE', N'Create workspace', N'Create a business workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222008', N'TENANT_MEMBER_READ', N'Read members', N'Read workspace members.', @Now, @Now), ('22222222-2222-4222-8222-222222222009', N'TENANT_MEMBER_INVITE', N'Invite members', N'Add a user to a workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222010', N'TENANT_MEMBER_REMOVE', N'Remove members', N'Remove a user from a workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222011', N'ROLE_READ', N'Read roles', N'Read role assignments in the workspace.', @Now, @Now), ('22222222-2222-4222-8222-222222222012', N'ROLE_ASSIGN', N'Assign roles', N'Assign or remove a workspace role.', @Now, @Now), ('22222222-2222-4222-8222-222222222013', N'LICENSE_READ', N'Read license', N'Read the workspace license.', @Now, @Now), ('22222222-2222-4222-8222-222222222014', N'FEATURE_READ', N'Read features', N'Read workspace feature flags.', @Now, @Now);
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r CROSS JOIN app.Permissions p WHERE r.Name = N'SuperAdmin';
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r INNER JOIN app.Permissions p ON p.Code IN ( N'USER_READ', N'USER_CREATE', N'USER_UPDATE', N'USER_DELETE', N'TENANT_READ', N'TENANT_UPDATE', N'TENANT_CREATE', N'TENANT_MEMBER_READ', N'TENANT_MEMBER_INVITE', N'TENANT_MEMBER_REMOVE', N'ROLE_READ', N'ROLE_ASSIGN', N'LICENSE_READ', N'FEATURE_READ') WHERE r.Name = N'GymOwner';
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r INNER JOIN app.Permissions p ON p.Code IN ( N'USER_READ', N'USER_UPDATE', N'TENANT_READ', N'TENANT_MEMBER_READ', N'TENANT_MEMBER_INVITE', N'ROLE_READ', N'LICENSE_READ', N'FEATURE_READ') WHERE r.Name = N'GymManager';
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r INNER JOIN app.Permissions p ON p.Code IN (N'USER_READ', N'TENANT_READ', N'TENANT_MEMBER_READ', N'FEATURE_READ') WHERE r.Name IN (N'Trainer', N'Receptionist');
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r INNER JOIN app.Permissions p ON p.Code IN (N'USER_READ', N'TENANT_READ', N'FEATURE_READ') WHERE r.Name = N'Member';
INSERT INTO app.RolePermissions (RoleId, PermissionId) SELECT r.Id, p.Id FROM app.Roles r INNER JOIN app.Permissions p ON p.Code IN ( N'USER_READ', N'USER_UPDATE', N'TENANT_READ', N'TENANT_UPDATE', N'TENANT_CREATE', N'TENANT_MEMBER_READ', N'LICENSE_READ', N'FEATURE_READ') WHERE r.Name = N'PersonalOwner';

rollback.sql:
DELETE FROM app.RolePermissions;
DELETE FROM app.Permissions;
DELETE FROM app.Roles;
